-- PT122-S1-Q14. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT122-S1-Q14$batch09$ AND q.stimulus=$batch09$Laila: Though lying may be unacceptable in most cases, there are exceptions: when lying brings about more good than harm, lying is morally permissible.$batch09$ AND q.prompt=$batch09$Which one of the following judgments conforms most closely to the principle stated by Laila?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT122-S1-Q14$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT122-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$If a lie brings about more good than harm, it is morally permissible.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The trigger is a comparison: the good the lie does has to outweigh the harm. A choice conforms only if it gives us enough to know the lie comes out ahead. Choices that check some other condition, like whether the activity is bad or who it affects, don't trigger the rule.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A lie judged permissible because it does more good than harm.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT122-S1-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The condition is that what Marcus does isn't bad. That doesn't tell us whether lying to Marcus's parents does more good than harm.$batch09$), ($batch09$B$batch09$, $batch09$Lying to the police about a possible criminal might do plenty of harm. B never weighs good against harm.$batch09$), ($batch09$C$batch09$, $batch09$A lie that affects only yourself can still do more harm than good. Who it affects isn't the test.$batch09$), ($batch09$D$batch09$, $batch09$The lie helps Thomas and does no harm. Some good and zero harm means more good than harm, so Laila's principle makes it permissible.$batch09$), ($batch09$E$batch09$, $batch09$The lie benefits the people deceived but "may harm others." We can't tell which side is bigger, so the rule isn't triggered.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT122-S1-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
